#include <iostream>
#include <string>
using namespace std;
class Student {
    string name;
    double grade;
public:
    Student(string n, double g=0) : name(n), grade(g) {}
    Student& operator--() { --grade; return *this; }
    Student operator--(int) { Student old(*this); --(*this); return old; }
    Student& operator++() { ++grade; return *this; } // Prefix.
    Student operator++(int) { // Postfix: unnamed dummy int distinguishes it.
        Student old(*this);
        ++(*this);
        return old;
    }
    friend ostream& operator<<(ostream& out, const Student& s) {
        return out << s.name << ' ' << s.grade;
    }
    friend istream& operator>>(istream& in, Student& s) {
        double value;
        if (in >> value) s.grade=value;
        return in;
    }
};

int main() {
    Student s("Hazem",65);
    cout << s-- << "\n" << s << "\n";
    cout << --s << "\n";
}
